argv:
$ErrorActionPreference='SilentlyContinue'
$dirs=Get-ChildItem 'E:\' -Directory -Force | Where-Object {$_.Name -ne 'manhwa'} | Select-Object -ExpandProperty FullName
$repos=@()
foreach($p in $dirs){
  if(Test-Path (Join-Path $p '.git')){
    $remote=(git -C $p remote get-url origin 2>$null)
    $branch=(git -C $p branch --show-current 2>$null)
    $head=(git -C $p rev-parse HEAD 2>$null)
    $repos += [pscustomobject]@{path=$p;remote=($remote -join '');branch=($branch -join '');head=($head -join '')}
  }
}
$ffmpeg=(where.exe ffmpeg 2>$null)
$ffprobe=(where.exe ffprobe 2>$null)
$runnerDirs=@($dirs | Where-Object {$_ -match 'actions-runner|github-runner|runner'})
[pscustomobject]@{
 repos=$repos
 ffmpeg=@($ffmpeg)
 ffprobe=@($ffprobe)
 runnerDirs=$runnerDirs
} | ConvertTo-Json -Depth 5 -Compress
